const CURRIC=[{nation:"England",text:"The National Curriculum for history (KS3) lists ‘Britain’s transatlantic slave trade’, the British Empire and Indian independence as non-statutory examples, so schools have discretion over how Black history is taught.",q:"Britain’s transatlantic slave trade: its effects and its eventual abolition",src:[SRCU("National curriculum in England: history programmes of study (DfE)","https://www.gov.uk/government/publications/national-curriculum-in-england-history-programmes-of-study/national-curriculum-in-england-history-programmes-of-study","")]},{nation:"England",text:"DfE says Black history can be taught across key stages, for example significant individuals at KS1 and a non-European society such as Benin (AD 900–1300) at KS2.",q:"The curriculum supports children learning about it all year round.",src:[SRCU("Black History Month: how Black history is taught in our schools (DfE Education Hub, Oct 2022)","https://educationhub.blog.gov.uk/2022/10/black-history-month-how-black-history-is-taught-in-our-schools-2/","")]},{nation:"England",text:"The Curriculum and Assessment Review final report (November 2025) calls for a curriculum that reflects the diversity of society. The quotes come from its general section 'A curriculum that reflects our society'. The history-specific section was not extracted, so its wording is unconfirmed.",q:"Young people have told us that not seeing themselves in the curriculum, or encountering negative portrayals, can be disempowering and demotivating",src:[SRCU("Curriculum and Assessment Review final report (deposited paper DEP2025-0723)","https://data.parliament.uk/DepositedPapers/Files/DEP2025-0723/Curriculum_and_Assessment_Review_final_report.pdf","")]},{nation:"England",text:"The Historical Association's response reads the review as recommending a history curriculum that includes British Black and Asian history, beyond Key Stage 3.",q:"We support the recommendation for a curriculum that reflects the innate diversity of British history, including British Black and Asian history.",src:[SRCU("Curriculum and Assessment Review Final Report – response (Historical Association, 6 Nov 2025)","https://www.history.org.uk/primary/news/4477/curriculum-and-assessment-review-final-report-re","")]},{nation:"Wales",text:"Wales became the first UK nation to make teaching Black, Asian and Minority Ethnic histories and experiences mandatory, through the Curriculum for Wales introduced from September 2022.",q:"make teaching of Black, Asian and Minority Ethnic histories and experiences mandatory in the school curriculum",src:[SRCU("Learning Black, Asian and Minority Ethnic histories included in new Welsh curriculum (Welsh Government, 1 Oct 2021)","https://www.gov.wales/learning-black-asian-and-minority-ethnic-histories-included-new-welsh-curriculum","")]},{nation:"Wales",text:"The Welsh Government confirms these histories are mandatory parts of the new curriculum.",q:"Learning about Welsh history and the history and diversity of communities, in particular the stories of Black, Asian and Minority Ethnic people, will be mandatory parts of the new curriculum.",src:[SRCU("Six things you may not know about the new curriculum (Welsh Government, 14 Jun 2022)","https://www.gov.wales/six-things-you-may-not-know-about-new-curriculum-wales","")]},{nation:"Scotland",text:"Curriculum for Excellence is supported by the Anti-Racism in Education Programme (est. 2021). One of its four workstreams is curriculum reform. It also aims for at least 4% of teachers to be from a minority ethnic background by 2030.",q:"articulate and embed anti-racism within a diverse and culturally-responsive curriculum",src:[SRCU("Anti-Racism in Education Programme: factsheet (Scottish Government, 7 Nov 2023)","https://www.gov.scot/publications/anti-racism-in-education-programme-factsheet/","")]},{nation:"Scotland",text:"The programme's anti-racist curriculum principles, 'Breaking the Mould', expect learners to enquire into Scotland's role in transatlantic enslavement.",q:"Will understand and enquire into Scotland's role in historical world events, including trans-Atlantic enslavement",src:[SRCU("Breaking the Mould: Anti-Racist Curriculum Principles (Education Scotland)","https://education.gov.scot/media/kzobbbhi/anti-racist-curriculum-principles-june-23.pdf","")]},{nation:"Scotland",text:"Under a May 2025 anti-racism commitment, everyone employed in Scottish education is asked to take anti-racist action.",q:"Racism exists within our education system, interpersonally and institutionally.",src:[SRCU("Anti-racism in education: commitment and guidance (Scottish Government, 20 May 2025)","https://www.gov.scot/publications/anti-racism-in-education-commitment-and-guidance/","")]},{nation:"Northern Ireland",text:"At Key Stage 3, the Northern Ireland Curriculum treats this through Local and Global Citizenship (Diversity and Inclusion), which covers ethnic diversity and racism. No source opened showed a specific statutory requirement for Black history in NI. This is unconfirmed, not ruled out.",q:"ideas of racism, prejudice, discrimination and how this is reflected in the way we talk about ethnic groups",src:[SRCU("CCEA Local and Global Citizenship KS3 Teachers' Notes","https://ccea.org.uk/document/4189","")]}];
const _cg={};CURRIC.forEach(c=>{if(!_cg[c.nation])_cg[c.nation]={nation:c.nation,text:"",src:[]};_cg[c.nation].text+=(_cg[c.nation].text?" ":"")+c.text;c.src.forEach(s=>{if(!_cg[c.nation].src.includes(s))_cg[c.nation].src.push(s)})});CURRIC.length=0;["England","Wales","Scotland","Northern Ireland"].forEach(n=>{if(_cg[n])CURRIC.push(_cg[n])});
