const COMM_FACTS=[{aud:"adultsw",fig:"~22%",t:"Staff from minoritised ethnic backgrounds make up around 22% of adult social care staff in councils covered by the SC-WRES.",per:"2025/26",cav:"Covers 99 participating local authorities (about 70% of the council adult social care workforce), not independent-sector providers.",q:"around 22% of adult social care staff",src:[SRCU("New Skills for Care report highlights inequity faced by people from global majority colleagues working in social care","https://skillsforcare-newsroom.prgloo.com/news/new-skills-for-care-report-highlights-inequity-faced-by-people-from-global-majority-colleagues-working-in-social-care","")]},{aud:"adultsw",fig:"37% less likely",t:"Black, Asian and minority ethnic staff are 37% less likely than white staff to be in senior management roles; 16% of shortlisted applicants appointed versus 28.8% of white applicants.",per:"2025/26",cav:"Relative likelihood from voluntary council returns; press summary, check full SC-WRES report for method. Quote reproduces the page's wording including its typo.",q:"37% less likely be working in senior management roles",src:[SRCU("New Skills for Care report highlights inequity faced by people from global majority colleagues working in social care","https://skillsforcare-newsroom.prgloo.com/news/new-skills-for-care-report-highlights-inequity-faced-by-people-from-global-majority-colleagues-working-in-social-care","")]},{aud:"adultsw",fig:"about 1 in 5",t:"In Wales ethnic minority staff are about one in five social care staff, yet under-represented in management and over twice as likely to lack progression training.",per:"2024",cav:"First Welsh baseline from 56,475 registered staff plus a survey; quote is the chief executive's statement, figures paraphrased.",q:"Racism is, and will always be, unacceptable.",src:[SRCU("New report finds discrimination against Black, Asian and Minority Ethnic social care workforce in Wales","https://socialcare.wales/news-stories/workforce-race-equality-standard-report-2024","")]},{aud:"childsw",fig:"10% vs 6%",t:"Black children were 10% of serious-incident reviews against 6% of England's under-18 population; Mixed Heritage children 17% against 7%.",per:"Jan 2022 – Mar 2024",cav:"Based on 54 reviews (53 children); small numbers. Asian children were under-represented (5% vs 12%).",q:"The silence around race and racism in child safeguarding practice is deeply concerning.",src:[SRCU("Safeguarding reviews silent on Black, Asian and Mixed Heritage children","https://www.gov.uk/government/news/safeguarding-reviews-silent-on-black-asian-and-mixed-heritage-children","")]},{aud:"childsw",fig:"8% and 11%",t:"Of children looked after in England on 31 March 2025, 8% were Black and 11% Mixed; Mixed-ethnicity children were over-represented against the child population.",per:"31 March 2025",cav:"Page does not state whether Black children are over-represented; a third of unaccompanied asylum-seeking children were Black, which affects the Black share.",q:"Children from Mixed ethnic groups were over-represented",src:[SRCU("Children looked after in England including adoptions, reporting year 2025","https://explore-education-statistics.service.gov.uk/find-statistics/children-looked-after-in-england-including-adoptions","")]},{aud:"childsw",fig:"Child Q (2022)",t:"A safeguarding review found racism and adultification bias were likely factors when a Black schoolgirl was strip-searched by police at school.",per:"March 2022",cav:"Single case review; illustrates a bias pattern rather than measuring prevalence.",q:"racism and 'adultification bias' were 'likely' influencing factors in what happened",src:[SRCU("Child Q update report: Hackney Council responds","https://news.hackney.gov.uk/child-q-update-report-hackney-council-responds","")]},{aud:"youth",fig:"15%",t:"Only one in seven youth sector organisations in England worked with young people experiencing racial or ethnic inequality.",per:"May–July 2021 survey",cav:"2021 initial findings from organisations that responded; may not reflect current provision. Provision was 20% in the most deprived areas vs 5% in the least.",q:"One in seven (15%) organisations work with young people experiencing racial or ethnic inequality.",src:[SRCU("Initial Summary of Findings from the National Youth Sector Census","https://nya.org.uk/wp-content/uploads/2024/02/initial-summary-Census-report-.pdf","")]},{aud:"youth",fig:"66%",t:"Of organisations supporting young people facing racial inequality, two-thirds supported young people with African, other Black or Caribbean backgrounds.",per:"May–July 2021 survey",cav:"Share of the 15% subset, not of all organisations.",q:"Two-thirds (66%) supported young people with African and other Black, or Caribbean backgrounds.",src:[SRCU("Initial Summary of Findings from the National Youth Sector Census","https://nya.org.uk/wp-content/uploads/2024/02/initial-summary-Census-report-.pdf","")]},{aud:"youth",fig:"42",t:"YouthLink Scotland's United Voices network had 42 member organisations, all Black-led, supporting young people facing racism.",per:"2024-25",cav:"Network membership count from the organisation's own annual report; Scotland only.",q:"The UV network has been a great support in promoting visibility and supporting the mental health of young people.",src:[SRCU("YouthLink Scotland Annual report 2024-25: Equality and Inclusion","https://www.youthlink.scot/annual-report-2024-25/equality-and-inclusion/","")]}];
